"""
Student Grades System

A module to manage courses, weighted assessments, letter-grade mappings, GPA calculation, class statistics, and transcript printing.
"""

from typing import List, Dict, Tuple, Optional
import json
import statistics

class GradeSystem:
    """Manages course assessments, scoring, grading, and statistics."""

    def __init__(self, config_path: str):
        """Initialize the grade system from a JSON config file."""
        with open(config_path, 'r') as f:
            self.config = json.load(f)

        self.courses = self.config['courses']
        self.weights = self.config['weights']
        self.grade_boundaries = self.config['grade_boundaries']
        self.letter_grades = sorted(self.grade_boundaries.keys(), key=lambda g: self.grade_boundaries[g]['min'], reverse=True)

    def calculate_weighted_score(self, course: str, assessments: Dict[str, float]) -> float:
        """Calculate weighted score for a given course and assessments."""
        weight_scheme = self.weights.get(course, {})
        weighted_score = 0.0
        for assess_name, weight in weight_scheme.items():
            score = assessments.get(assess_name, 0.0)
            weighted_score += score * weight
        return weighted_score

    def score_to_letter(self, score: float) -> str:
        """Convert numeric score to letter grade using boundaries."""
        for grade in self.letter_grades:
            boundary = self.grade_boundaries[grade]
            if boundary['min'] <= score <= boundary['max']:
                return grade
        return 'F'  # default fail

    def letter_to_gpa(self, letter: str) -> float:
        """Map letter grade to GPA points."""
        return self.grade_boundaries.get(letter, {}).get('gpa_points', 0.0)

    def calculate_gpa(self, grades: Dict[str, str]) -> float:
        """Calculate GPA from letter grades."""
        total_points = 0.0
        count = 0
        for course, letter in grades.items():
            if letter:
                total_points += self.letter_to_gpa(letter)
                count += 1
        return total_points / count if count > 0 else 0.0

    def class_statistics(self, scores: Dict[str, List[float]]) -> Dict[str, Dict[str, float]]:
        """Calculate statistics (mean, median, stdev) for each course."""
        stats = {}
        for course, marks in scores.items():
            if marks:
                stats[course] = {
                    'mean': statistics.mean(marks),
                    'median': statistics.median(marks),
                    'stdev': statistics.stdev(marks) if len(marks) > 1 else 0.0
                }
        return stats

    def print_transcript(self, student_name: str, grades: Dict[str, Tuple[float, str]]) -> str:
        """Generate a transcript string for the student."""
        lines = [f"Transcript for {student_name}:\n"]
        lines.append(f"{'Course':<15}{'Score':<10}{'Grade':<10}")
        total_gpa_points = 0.0
        count = 0
        for course, (score, letter) in grades.items():
            lines.append(f"{course:<15}{score:<10.2f}{letter:<10}")
            if letter:
                total_gpa_points += self.letter_to_gpa(letter)
                count += 1
        gpa = total_gpa_points / count if count > 0 else 0.0
        lines.append(f"\nGPA: {gpa:.2f}")
        return '\n'.join(lines)


def demo():
    """Run a demo of the student grade system."""
    system = GradeSystem('config.json')

    # Sample students data
    students = {
        'Alice': {
            'Math': {'Homework': 85, 'Midterm': 78, 'Final': 92},
            'English': {'Essay': 88, 'Midterm': 90, 'Final': 85},
            'History': {'Project': 70, 'Midterm': 82, 'Final': 78}
        },
        'Bob': {
            'Math': {'Homework': 92, 'Midterm': 88, 'Final': 85},
            'English': {'Essay': 75, 'Midterm': 78, 'Final': 80},
            'History': {'Project': 82, 'Midterm': 85, 'Final': 88}
        },
        'Cathy': {
            'Math': {'Homework': 76, 'Midterm': 69, 'Final': 80},
            'English': {'Essay': 93, 'Midterm': 95, 'Final': 94},
            'History': {'Project': 88, 'Midterm': 90, 'Final': 85}
        },
    }

    # Calculate grades for students
    student_grades = {}
    all_scores = {course: [] for course in system.courses}

    for student, course_assessments in students.items():
        student_grades[student] = {}
        for course, assessments in course_assessments.items():
            weighted_score = system.calculate_weighted_score(course, assessments)
            letter = system.score_to_letter(weighted_score)
            student_grades[student][course] = (weighted_score, letter)
            all_scores[course].append(weighted_score)

    # Print transcripts and class stats
    for student, grades in student_grades.items():
        print(system.print_transcript(student, grades))
        print("---")

    stats = system.class_statistics(all_scores)
    print("Class Statistics:")
    for course, stat in stats.items():
        print(f"{course}: Mean={stat['mean']:.2f}, Median={stat['median']:.2f}, StdDev={stat['stdev']:.2f}")


if __name__ == '__main__':
    demo()
